import {genesisPanel,initGenesisPanel} from "./genesis-structure.js";
import {bookLinks,storyCard,eraPager,renderEraSheet,renderEraOverview} from "./history-sheet-ui.js";
import {loadHistoryData} from "./history-data.js";
import {ERA_SLUGS,eraFromLocation,navigateToEra} from "./history-routing.js";
const $=s=>document.querySelector(s),esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const historySkeleton=()=>`<div class="kb-history-skeleton" role="status" aria-label="Cargando contenido de la era"><span class="kb-skeleton-line kb-skeleton-title" aria-hidden="true"></span><span class="kb-skeleton-line kb-skeleton-short" aria-hidden="true"></span><span class="kb-skeleton-card" aria-hidden="true"></span><span class="kb-skeleton-line" aria-hidden="true"></span><span class="kb-skeleton-card" aria-hidden="true"></span></div>`;async function main(){const data=await loadHistoryData();const eras=data.eras;const slugs=ERA_SLUGS;const basePath=new URL("./history/",import.meta.url).pathname;let active=eraFromLocation(basePath);if(!eras.some(e=>e.id===active))active=eras[0].id;let hasRenderedScale=false;let renderToken=0;const select=(id,move=false)=>{const token=++renderToken;active=id;const i=eras.findIndex(e=>e.id===id),era=eras[i],bib=i<6;$("#scale").innerHTML=eras.map((e,j)=>'<button aria-label="'+esc(e.title)+'" title="'+esc(e.title)+'" class="'+(e.date.precision==="undated"||e.date.precision==="debated"?"uncertain ":"")+(j===i?"active":"")+'" style="--c:'+esc(e.color)+'" data-id="'+esc(e.id)+'"></button>').join("");if(!hasRenderedScale){$("#scale").classList.add("kb-scale-enter");hasRenderedScale=true}else{$("#scale").classList.remove("kb-scale-enter")}$("#scale-numbers").innerHTML=eras.map((e,j)=>'<button class="'+(i===j?"active":"")+'" data-id="'+esc(e.id)+'" aria-label="Era '+(j+1)+': '+esc(e.title)+'" aria-current="'+(i===j?'step':'false')+'">'+(j+1)+'</button>').join("");$("#group-label").textContent=bib?"Historia bíblica":"Cristianismo";$("#group-count").textContent=bib?"6 eras":"4 eras";$("#selector .group-title").classList.toggle("christian",!bib);const detail=$("#era-detail");detail.style.removeProperty("min-height");detail.setAttribute("aria-busy","true");detail.innerHTML=historySkeleton();const strip=$("#era-strip");strip.querySelectorAll(".era[data-id]").forEach(chip=>{chip.setAttribute("aria-pressed",String(chip.dataset.id===id))});window.setTimeout(()=>{if(token!==renderToken)return;const ev=data.events.filter(e=>e.eraId===id).sort((a,b)=>a.order-b.order);$("#era-detail").setAttribute("aria-busy","false");$("#era-detail").style.setProperty("--gc",bib?"var(--green)":"var(--gold)");const stories=(data.stories||[]).filter(x=>x.eraId===id).sort((a,b)=>a.order-b.order);const currentStory=stories.find(x=>location.pathname.includes("/"+x.id+"/"));const periods=(data.subEras||[]).filter(x=>x.eraId===id).sort((a,b)=>a.order-b.order);const periodNav=periods.length?'<nav class="kb-periods" aria-label="Periodos de la era"><button type="button" class="kb-period active" data-period="all" aria-pressed="true">Todos</button>'+periods.map(p=>'<button type="button" class="kb-period" data-period="'+esc(p.id)+'" aria-pressed="false">'+esc(p.title)+'</button>').join("")+'</nav>':"";const bookNav=bookLinks(era,new URL("./index.html",import.meta.url).pathname);const card=x=>storyCard(x,basePath+slugs[id]+"/"+x.id+"/",x.cover?.src?new URL("./"+x.cover.src,import.meta.url).pathname:"");if(stories.length){$("#era-detail").innerHTML=currentStory?'<a class="kb-story-back" href="'+basePath+slugs[id]+'/">← Todas las historias</a><p class="plate-kicker">'+esc(era.title)+' · '+currentStory.order+' de '+stories.length+'</p><h2>'+esc(currentStory.title)+'</h2><p class="plate-sub">'+esc(currentStory.reference)+'</p><p class="summary">'+esc(currentStory.summary)+'</p><a class="kb-read" href="'+new URL("./index.html",import.meta.url).pathname+'?book=genesis&chapter='+currentStory.chapter+'">Leer en Génesis ↗</a>':renderEraSheet({era,books:bookNav,body:'<section class="kb-story-section" aria-label="Relatos de '+esc(era.title)+'"><div class="kb-story-heading"><h3>Relatos</h3><span>'+stories.length+' '+(stories.length===1?'historia':'historias')+'</span></div><p class="kb-story-context">'+esc(era.subtitle)+'</p>'+periodNav+'<div class="kb-story-grid">'+stories.map(card).join("")+'</div></section>'+genesisPanel(data,id,basePath,slugs[id]),navigation:eraPager(eras,i)});if(!currentStory)initGenesisPanel($("#era-detail"));if(!currentStory&&periods.length){document.querySelectorAll(".kb-period").forEach(btn=>btn.addEventListener("click",()=>{const period=btn.dataset.period;document.querySelectorAll(".kb-period").forEach(b=>{const selected=b===btn;b.classList.toggle("active",selected);b.setAttribute("aria-pressed",String(selected))});document.querySelectorAll(".kb-story").forEach(card=>{const story=stories.find(x=>card.getAttribute("href").endsWith("/"+x.id+"/"));card.hidden=period!=="all"&&story?.subEraId!==period})}))}if(!currentStory)navigateToEra(basePath,id);return}$("#era-detail").innerHTML=renderEraOverview({era,books:bookNav,navigation:eraPager(eras,i)});if(!currentStory)navigateToEra(basePath,id,id===eras[0].id&&location.pathname===basePath);if(move){const b=$("#era-strip .era[aria-pressed=true]");if(b){const strip=$("#era-strip");const left=b.offsetLeft-(strip.clientWidth-b.offsetWidth)/2;strip.scrollTo({left,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth"})}}},330)};window.addEventListener("popstate",()=>{const id=eraFromLocation(basePath)||eras[0].id;select(id)});document.body.addEventListener("click",e=>{const b=e.target.closest("button[data-id]");if(b?.dataset.id){const fromBottom=Boolean(b.closest(".kb-era-nav"));select(b.dataset.id,true);if(fromBottom)$("#era-detail").scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth",block:"start"})}});select(active)}main().catch(e=>{$("#era-detail").innerHTML='<p>No se pudo cargar la cronología. <button onclick="location.reload()">Reintentar</button></p>';console.error(e)});